{
  "a_sentences": [
    {
      "a_text": "P1 La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en admettant la compétence de l'assureur Stadt Uster pour fixer et verser les prestations complémentaires à l'intimée.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 L'intimée perçoit une rente pour enfant de l'assurance-invalidité depuis le 1er décembre 2024.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 L'art. 21 al. 1 LPC prévoit que la compétence pour fixer et verser les prestations complémentaires appartient au canton de domicile du bénéficiaire.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 L'art. 9 al. 2 LPC prescrit que les dépenses reconnues et les revenus déterminants des conjoints et des personnes avec des orphelins ou des enfants donnant droit à une rente pour enfant de l'AVS ou de l'AI sont additionnés.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Selon l'art. 9 al. 2 LPC en lien avec l'art. 7 al. 1 let. b OPC-AVS/AI, si l'enfant vit uniquement avec un parent rentier ou ayant droit à une rente complémentaire de l'AVS, la prestation complémentaire est calculée avec ce parent.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Le Tribunal fédéral confirme la compétence de l'assureur Stadt Uster pour fixer et verser les prestations complémentaires à l'intimée, dès lors que celle-ci vit avec sa mère également rentière à Uster.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Le Tribunal fédéral retient que la juridiction cantonale n'a pas violé le droit fédéral en confirmant la compétence de l'assureur Stadt Uster sur la base du principe de calcul global prévu par l'art. 9 al. 2 LPC en lien avec l'art. 7 al. 1 let. b OPC-AVS/AI.",
      "b_propositions": ["P7"]
    }
  ]
}
